export function findSpatialGeometriesById(id: string): SpatialGeometryRecord | undefined {
  return SPATIAL_GEOMETRIES_DATABASE.find(item => item.id === id);
}

export function getAllSpatialGeometriesRecords(): SpatialGeometryRecord[] {
  return SPATIAL_GEOMETRIES_DATABASE;
}

export function filterSpatialGeometriesByPredicate(predicate: (item: SpatialGeometryRecord) => boolean): SpatialGeometryRecord[] {
  return SPATIAL_GEOMETRIES_DATABASE.filter(predicate);
}

export function countSpatialGeometriesRecords(): number {
  return SPATIAL_GEOMETRIES_DATABASE.length;
}
